  ],
  "conditions_and_exceptions": "El atleta no puede continuar mientras esté sangrando [SOR-2026-08-P198-S209]. Puede continuar compitiendo únicamente una vez que el sangrado esté completamente controlado y aislado [SOR-2026-08-P198-S209]. Se permite recibir tratamiento médico para el sangrado en dos ocasiones únicamente [SOR-2026-08-P198-S209]. Si se necesita tratamiento por tercera vez, el árbitro declarará al oponente ganador por kiken-gachi, a menos que la Comisión AdHoc de la IJF, en consulta con la Comisión Médica de la IJF, autorice una excepción para tratamientos adicionales [SOR-2026-08-P198-S209].",
  "extended_analysis": "No aplica.",
  "limitations": "Ninguna",
  "answerability": "RESPALDADA",
  "evidence_quotes": [
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete is not allowed to compete while bleeding.",
      "supports": "El atleta no tiene permitido competir mientras está sangrando."
    },
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete may continue competing only once the bleeding is fully controlled and isolated.",
      "supports": "El atleta puede continuar compitiendo solo una vez que el sangrado esté totalmente controlado y aislado."
    },
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "The athlete is allowed to receive medical treatment for bleeding, on two (2) occasions only.",
      "supports": "Al atleta se le permite recibir tratamiento médico por sangrado en dos ocasiones únicamente."
    },
    {
      "passage_id": "SOR-2026-08-P198-S209",
      "quote": "If treatment is needed for a third time, the referee shall declare the opponent the winner by kiken-gachi",
      "supports": "Si se necesita tratamiento por tercera vez, el árbitro declarará al oponente ganador por kiken-gachi."
    }
  ],
  "evidence_conflicts": []
}

